import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"晶圆形变与应力","description":"","frontmatter":{"title":"晶圆形变与应力","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/wafer-distortion-stress.md","filePath":"litho/wafer-distortion-stress.md","lastUpdated":1789023840000}'),E={name:"litho/wafer-distortion-stress.md"};function c(_,a,B,m,f,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="晶圆形变与应力" tabindex="-1">晶圆形变与应力 <a class="header-anchor" href="#晶圆形变与应力" aria-label="Permalink to &quot;晶圆形变与应力&quot;">​</a></h1><div class="epigraph"><p>薄膜应力把圆片弯成碗或马鞍，对准看见膨胀与旋转，器件网格却按薄膜历史走；补的是形变，不是镜头放大。</p><footer>—— 对照晶圆翘曲、工艺诱导 overlay 与 ASML 对 process-induced overlay 的公开论述</footer></div><p><a href="/litho/edge-field-partial">上一课</a>处理边缘边界。缺口是整片：沉积、CMP、退火、背面膜让晶圆翘曲，曝光时卡盘强行吸平，释放后又弹回。<a href="/litho/wafer-thermal-overlay">晶圆热套刻</a> 已谈热；本课钉应力形变。机台对机台套刻，留给[下一课](/litho/tool-to-tool-overlay）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>应力 overlay 的典型指纹：径向放大、枕形、不对称弯月，随层叠厚度变。对准在吸盘上读到一个网格，器件在自由或不同吸平状态下是另一个。高阶场内项可以部分吃掉，但应力若随产品布局（密金属区）走，全球多项式不够，需要高密度计量或分区。</p><p>缺口是<strong>工艺诱导套刻是集成问题</strong>，不是扫描机坏了。只匹配镜头的厂，会在新 PECVD 或厚铜层后「套刻突然失控」。</p><h3 id="吸平不是可逆的" tabindex="-1">吸平不是可逆的 <a class="header-anchor" href="#吸平不是可逆的" aria-label="Permalink to &quot;吸平不是可逆的&quot;">​</a></h3><p>卡盘吸平能压低翘曲，接触不良、背面颗粒会造成局部鼓包，焦点与套刻一起坏。真空吸盘与边缘接触策略是扫描机课已有的硬件；本课要求应力大的层检查吸平质量，而不是只加校正项。</p><p><span class="marginnote">双面加工与背面电源把应力源翻到背面，对准树和翘曲模型都要重做。助推器课点过 BPR；这里是控制后果。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：翘曲仪、高密度套刻、对准残差图。动作：薄膜应力工程、退火、补偿层、扫描机高阶 + 晶圆专用校正。与 APC：应力指纹慢变，可当产品–层的静态地图，不要当片噪声。与标记：应力下标记相对器件滑动，关键对尽量用产品附近标记。</p><p>新薄膜或新退火导入等于新地图：要加密套刻直到指纹稳定，再降回稳态抽样。process-induced overlay 的公开论述把工艺当指纹源；本课要求源变则地图版本变。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>薄膜应力 \\(\\sigma\\) 产生弯矩，晶圆曲率 \\(\\propto \\sigma h_\\mathrm{film}\\)。卡盘约束改变曝光时的面内应变。曝光后释放，层间相对位移留下。热与应力耦合：温度改应力状态。R2R 若把应力放大当镜头放大去补，换产品场排布即失败——分账与高阶课同一原则。</p>',14)),(e(),n(h,null,{default:r(()=>[p(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILM%5B%22%E8%96%84%E8%86%9C%E5%BA%94%E5%8A%9B%20%2F%20%E9%80%80%E7%81%AB%22%5D%20--%3E%20WARP%5B%22%E7%BF%98%E6%9B%B2%22%5D%0A%20%20WARP%20--%3E%20CHUCK%5B%22%E5%90%B8%E5%B9%B3%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20CHUCK%20--%3E%20GRID%5B%22%E6%9B%9D%E5%85%89%E6%97%B6%E7%BD%91%E6%A0%BC%22%5D%0A%20%20REL%5B%22%E9%87%8A%E6%94%BE%20%2F%20%E5%90%8E%E5%B1%82%22%5D%20--%3E%20OVL%5B%22%E5%B1%82%E9%97%B4%E5%B7%A5%E8%89%BA%E5%A5%97%E5%88%BB%22%5D%0A%20%20GRID%20--%3E%20OVL%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>吸平约束下曝光、释放后弹回，层间留下工艺套刻。全球放大项冒充弯月，换场排布即崩。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写材料力学全文。不把某层未公开的翘曲微米数当规格。封装翘曲只点名，细节不在光刻控制课展开。</p><p>后课默认：工艺诱导指纹按产品–层存地图。下一课多机时，这些地图还要叠机台差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应力形变造成工艺诱导套刻，应工程减源并配静态地图。</li><li>吸平质量是焦点+套刻的共同前置。</li><li>全球放大项不能冒充应力弯月。</li><li>出处：process-induced overlay 公开论述；ASML 翘曲相关公开材料。</li></ul>',6))])}const D=i(E,[["render",c]]);export{P as __pageData,D as default};
